<?php
require 'includes/db.php';
session_start();
if(empty($_SESSION['student_id'])){header('Location: login.php?login_required=1');exit;}
$q=$pdo->prepare('SELECT s.* FROM scholarships s JOIN student_favourites f ON f.scholarship_id=s.id WHERE f.student_id=? ORDER BY f.created_at DESC');$q->execute([$_SESSION['student_id']]);$saved=$q->fetchAll();
$soon=[];$today=new DateTimeImmutable('today');
foreach($saved as $s){if(!empty($s['deadline'])){$d=new DateTimeImmutable($s['deadline']);$days=(int)$today->diff($d)->format('%r%a');if($days>=0&&$days<=30)$soon[]=$s;}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Dashboard | ScholarConnect Pro</title><link rel="stylesheet" href="css/style.css"></head><body><?php include 'includes/header.php';?><header class="page-header"><span class="eyebrow">STUDENT DASHBOARD</span><h1>Welcome, <?=htmlspecialchars($_SESSION['student_name']??'Student')?> 👋</h1><p>Keep your favourite scholarships in one place and watch important deadlines.</p></header><section class="directory"><div class="dashboard-stats"><div class="dashboard-stat-card"><span class="dashboard-stat-icon">★</span><strong><?=count($saved)?></strong><span>Saved scholarships</span></div><div class="dashboard-stat-card"><span class="dashboard-stat-icon">⏰</span><strong><?=count($soon)?></strong><span>Closing within 30 days</span></div></div><div class="section-heading"><div><span class="eyebrow">YOUR SAVED LIST</span><h2>Favourite Scholarships</h2><p class="dashboard-subtitle">Quick access to the scholarships you want to keep track of.</p></div><a class="btn btn-light" href="scholarships.php">Browse Scholarships →</a></div><?php if(!$saved):?><div class="empty">You have no saved scholarships yet. Open a scholarship and choose “Save”.</div><?php else:?><div class="card-grid"><?php foreach($saved as $s):?><article class="scholarship-card"><div class="card-top"><span class="tag"><?=htmlspecialchars($s['category'])?></span><span class="tag soft"><?=htmlspecialchars($s['course'])?></span><?php if(!empty($s['deadline'])):?><span class="tag <?=((new DateTimeImmutable($s['deadline']))<new DateTimeImmutable('today'))?'status-closed':'status-open'?>"><?=htmlspecialchars(date('d M Y',strtotime($s['deadline'])))?></span><?php endif;?></div><h3><?=htmlspecialchars($s['name'])?></h3><p class="department"><?=htmlspecialchars($s['department'])?></p><p><?=htmlspecialchars($s['benefit'])?></p><div class="card-actions"><a class="btn btn-small btn-light" href="scholarships.php?id=<?=$s['id']?>">View Details</a><a class="btn btn-small btn-primary" target="_blank" href="<?=htmlspecialchars($s['official_url'])?>">Official ↗</a><a class="btn btn-small favorite-remove" href="favorite.php?id=<?=$s['id']?>&back=dashboard.php"><span>★</span> Remove</a></div></article><?php endforeach;?></div><?php endif;?></section><?php include 'includes/footer.php';?></body></html>
